--
-- Name: log_deleted_sc_record(); Type: FUNCTION; Schema: public; Owner: dbremote
--

CREATE FUNCTION log_deleted_sc_record() RETURNS trigger
    LANGUAGE plpgsql NOT SHIPPABLE
 AS $$
BEGIN
    VALUES (OLD."S_num", OLD."C_num", OLD."GRADE", NOW());
    RETURN OLD;
END;
$$;


ALTER FUNCTION public.log_deleted_sc_record() OWNER TO dbremote;

