--
-- Name: sc799_partitioned; Type: TABLE; Schema: public; Owner: dbremote; Tablespace: 
--

CREATE TABLE sc799_partitioned (
    "S_num" character varying(20) NOT NULL,
    "C_num" character varying(20) NOT NULL,
    "GRADE" numeric(4,1)
)
WITH (orientation=row, compression=no)
PARTITION BY RANGE ("S_num")
(
    PARTITION sc799_p0 VALUES LESS THAN ('03000000'),
    PARTITION sc799_p1 VALUES LESS THAN ('06000000'),
    PARTITION sc799_p2 VALUES LESS THAN ('09000000'),
    PARTITION sc799_p3 VALUES LESS THAN (MAXVALUE)
)
ENABLE ROW MOVEMENT;


